SELECT SUM(BIT_AND(x3.v180995)) OVER (), SUM(2 + SUM(x3.v180995)) OVER (ORDER BY x3.v180995 DESC, x3.v180995 ASC, x3.v180996 DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM v180994 AS x3 WINDOW x1 AS (PARTITION BY x3.v180996 ORDER BY x3.v180996 ROWS BETWEEN 3.4 PRECEDING AND 2 FOLLOWING)